def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    for comp in components(g == bg):
        if any(y == 0 or x == 0 or y == H - 1 or x == W - 1 for y, x in comp):
            continue
        for y, x in comp:
            out[y, x] = 1
        emit(out, f"Filled enclosed background region of {len(comp)} cells (bbox {bbox(comp)}) with colour 1.")
    emit(out, "All enclosed regions filled; regions touching the border stay background.")
    return out
